const data = $input.first().json;
const action = data.action;
const userId = data.userId;
const chatId = data.chatId;
const params = data.params || {};

let sql = '';
let responseTemplate = '';

switch (action) {
  case 'vincular': {
    // Link Telegram account with platform user
    const username = params.username;
    if (!username) {
      return [{ json: { chatId, skip: true, text: '❌ Uso: /vincular tu_nombre_de_usuario\n\nEjemplo: /vincular ProGamer123' }}];
    }
    sql = `UPDATE users SET telegram_chat_id = '${chatId}' WHERE username = '${username.replace(/'/g, "''")}' AND telegram_chat_id IS NULL`;
    responseTemplate = 'vincular';
    break;
  }

  case 'reportar': {
    // Report match result: /reportar <match_number> <my_score> <opponent_score>
    const matchNum = parseInt(params.matchNumber);
    const myScore = parseInt(params.myScore);
    const oppScore = parseInt(params.oppScore);
    if (!matchNum || isNaN(myScore) || isNaN(oppScore)) {
      return [{ json: { chatId, skip: true, text: '❌ Uso: /reportar <numero_partido> <mi_score> <score_oponente>\n\nEjemplo: /reportar 5 3 1' }}];
    }
    // First verify user is linked and find their team
    sql = `SELECT m.id as match_id, m.home_team_id, m.away_team_id, m.status,\n  tp.team_id, t.name as team_name\n  FROM users u\n  JOIN team_players tp ON tp.user_id = u.id\n  JOIN teams t ON tp.team_id = t.id\n  JOIN matches m ON m.tournament_id = t.tournament_id AND m.match_number = ${matchNum}\n    AND (m.home_team_id = t.id OR m.away_team_id = t.id)\n  WHERE u.telegram_chat_id = '${chatId}'\n  AND m.status IN ('SCHEDULED', 'LIVE', 'CHECK_IN')\n  LIMIT 1`;
    responseTemplate = 'reportar_check';
    break;
  }

  case 'reportar_confirm': {
    // Actually insert the result after verification
    const matchId = params.matchId;
    const teamId = params.teamId;
    const myScore = parseInt(params.myScore);
    const oppScore = parseInt(params.oppScore);
    const isHome = params.isHome;
    const winnerId = myScore > oppScore ? teamId : params.opponentTeamId;
    const homeScore = isHome ? myScore : oppScore;
    const awayScore = isHome ? oppScore : myScore;

    sql = `UPDATE matches SET home_score = ${homeScore}, away_score = ${awayScore}, winner_id = '${winnerId}', status = 'COMPLETED', updated_at = NOW() WHERE id = '${matchId}' AND status IN ('SCHEDULED', 'LIVE', 'CHECK_IN')`;
    responseTemplate = 'reportar_done';
    break;
  }

  case 'inscribir': {
    // Quick tournament registration: /inscribir <tournament_name>
    const tournamentSearch = params.tournamentName || '';
    if (!tournamentSearch) {
      return [{ json: { chatId, skip: true, text: '❌ Uso: /inscribir <nombre_torneo>\n\nEjemplo: /inscribir Apex Championship' }}];
    }
    sql = `SELECT t.id, t.name, t.status, t.team_size, t.entry_fee,\n  (SELECT COUNT(*) FROM teams WHERE tournament_id = t.id) as team_count, t.max_participants\n  FROM tournaments t\n  WHERE t.name LIKE '%${tournamentSearch.replace(/'/g, "''")}%'\n  AND t.status = 'REGISTRATION_OPEN'\n  ORDER BY t.start_date ASC LIMIT 3`;
    responseTemplate = 'inscribir_check';
    break;
  }

  default:
    return [{ json: { chatId, skip: true, text: '❌ Acción no reconocida.' }}];
}

return [{ json: { sql, chatId, userId, action, responseTemplate, params } }];

