      msg = `✅ Partido #${params.matchNumber} encontrado\n\n🏆 Tu equipo: ${r.team_name}\n📊 Resultado reportado: ${params.myScore} - ${params.oppScore}\n\n⏳ Procesando resultado...`;

      // Note: In production, this would trigger the reportar_confirm action
      // For now, we report the result directly
    }
    break;
  }

  case 'reportar_done': {
    if (affectedRows > 0) {
      msg = '✅ ¡Resultado reportado exitosamente!\n\n📊 El resultado ha sido registrado y el bracket actualizado.\nPuedes ver el estado con /envivo o /torneos';
    } else {
