    }
    break;
  }

  case 'inscribir_check': {
    if (rows.length === 0 || !rows[0].name) {
      msg = '😔 No encontré torneos abiertos con ese nombre.\n\nUsa /torneos para ver los torneos disponibles.';
    } else {
